const rtdal003080Source0001 = "plot.Intervals_full <- function(\n                                x, y = NULL,\n                                axes = TRUE,\n                                xlab = \"\", ylab = \"\",\n                                xlim = NULL, ylim = NULL,\n                                col = \"black\", lwd = 1,\n                                cex = 1,\n                                use_points = TRUE,\n                                use_names = TRUE,\n                                names_cex = 1,\n                                ...\n                                )\n{\n  # Subset first, for efficiency, and so that the maximal y plotted is\n  # appropriate for the region shown.\n\n  if ( any( is.na( x ) ) ) x <- x[ !is.na(x), ]\n  \n  if ( is.null(xlim) )\n    xlim <- range( x@.Data )\n  else\n    x <- x[ x[,2] >= xlim[1] & x[,1] <= xlim[2], ]\n  \n  if ( is.null(y) )\n    y <- .Call( `_plot_overlap`, x@.Data, closed(x), is( x, \"Intervals_full\" ) )\n\n  if ( is.null(ylim) )\n    ylim <- c( 0, max( y ) )\n\n  plot(\n       0, 0,\n       type = \"n\",\n       xlim = xlim, ylim = ylim,\n       axes = FALSE,\n       xlab = xlab, ylab = ylab,\n       ...\n       )\n  # Careful with non-finite endpoints, which segments() ignores.\n  segments(\n           pmax( x[,1], par(\"usr\")[1] ), y,\n           pmin( x[,2], par(\"usr\")[2] ), y,\n           col = col,\n           lwd = lwd\n           )\n  if ( use_points ) {   \n    # Careful with points...\n    adjust <- ( x[,1] == x[,2] ) & !closed(x)[,1]\n    closed(x)[ adjust, 2 ] <- FALSE\n    points(\n           x@.Data, rep( y, 2 ),\n           pch = 21, cex = cex,\n           col = col, bg = ifelse( closed(x), col, \"white\" )           \n           )\n  }\n  if ( use_names && !is.null( rownames(x) ) ) {\n    mids <- ( x[,1] + x[,2] ) / 2\n    text(\n         mids, y,\n         rownames( x ),\n         pos = 3, offset = .5,\n         cex = names_cex,\n         xpd = NA\n         )         \n  }\n  if ( axes )\n    axis( 1 )\n}"

