const rtdal003105Source0001 = "test_that(\"conversion of isolines to sfg\", {\n  #m <- matrix(c(0, 0, 0, 2,\n  #              0, 1, 0, 2,\n  #              0, 0, 0, 0), 3, 4, byrow = TRUE)\n  #lines <- isolines(1:4, 3:1, m, c(0.5, 1.5))\n\n  lines <- structure(\n    list(\n      `0.5` = list(\n        x = c(2.00, 2.50, 2.00, 1.50, 2.00, 3.25, 3.25, 4.00),\n        y = c(1.50, 2.00, 2.50, 2.00, 1.50, 3.00, 2.00, 1.25),\n        id = c(1, 1, 1, 1, 1, 2, 2, 2)\n      ),\n      `1.5` = list(\n        x = c(3.75, 3.75, 4.00),\n        y = c(3.00, 2.00, 1.75),\n        id = c(1, 1, 1)\n      )\n    ),\n    class = c(\"isolines\", \"iso\")\n  )\n\n  out <- iso_to_sfg(lines)\n\n  expect_equal(\n    out[[\"0.5\"]][[1]],\n    cbind(\n      c(2.00, 2.50, 2.00, 1.50, 2.00),\n      c(1.50, 2.00, 2.50, 2.00, 1.50)\n    )\n  )\n\n  expect_equal(\n    out[[\"0.5\"]][[2]],\n    cbind(\n      c(3.25, 3.25, 4.00),\n      c(3.00, 2.00, 1.25)\n    )\n  )\n\n  expect_equal(\n    class(out[[\"0.5\"]]),\n    c(\"XY\", \"MULTILINESTRING\", \"sfg\")\n  )\n\n  expect_equal(\n    out[[\"1.5\"]][[1]],\n    cbind(\n      c(3.75, 3.75, 4.00),\n      c(3.00, 2.00, 1.75)\n    )\n  )\n\n  expect_equal(\n    class(out[[\"1.5\"]]),\n    c(\"XY\", \"MULTILINESTRING\", \"sfg\")\n  )\n})"

