const rtdal003113Source0001 = `jquery_core <- function(major_version = 3, minified = getOption("shiny.minified", TRUE)) {
  version <- expand_version(major_version)
  script <- paste0("jquery-", version, if (minified) ".min.js" else ".js")
  htmlDependency(
    "jquery", version,
    src = list(file = file.path("lib", version)),
    package = "jquerylib",
    script = script
  )
}`

