const rtdal003128Source0006 = `test_that("arrays of arrays of same length go to matrix",{
  
  js <- '[[1,2],[3,4],[5,6]]'
  x <- from_json( js )
  expect_equal(x, matrix(1:6, ncol = 2, byrow = T ) )
  
})`

const rtdal003128Source0007 = `test_that("array of arrays of different lenghts go to list",{
  
  ## issue 67
  js <- '[1,[2]]'
  x <- from_json( js )
  expect_equal(x, list(1,2))
  
  js <- '{"test":[1,[2,[3]]]}'
  x <- from_json( js )
  expect_equal(x, list(test = list(1,list(2,3))))
  
  x <- from_json( js, simplify = FALSE )
  expect_equal(x, list(test = list(1,list(2,list(3)))))
  
  js <- '[[1,2],[1,2,3]]'
  x <- from_json( js )
  expect_equal( x, list(1:2, 1:3))

  js <- '[[5,[6,7]]]'
  x <- from_json( js )
  expect_equal( x, list( list( 5, 6:7 )  ) ) 
  
  js <- '[[5,[6,"a"]]]'
  x <- from_json( js )
  expect_equal( x, list( list( 5, c("6","a") )  ) )
  
  js <- '[[1,2],[3,4],[5,[6,7]]]'
  x <- from_json( js )
  expect_equal( x, list( c(1,2), c(3,4), list(5, 6:7) ) )
})`

const rtdal003128Source0008 = `test_that("array of various types converted to matrices",{
  
  js <- '[[1,2],[3,4]]'
  x <- from_json( js )
  expect_equal(x, matrix(1L:4L, ncol = 2, byrow = T ) )
  
  js <- '[[1.1,2],[3,4]]'
  x <- from_json( js )
  expect_equal(x, matrix(c(1.1,2,3,4), ncol = 2, byrow = T ) )
})`

