const rtdal003264Source0001 = `hook_pdfcrop = function(before, ...) {
  # crops plots after a chunk is evaluated and plot files produced
  if (before) return()
  in_base_dir(for (f in get_plot_files()) plot_crop(f))
}`

const rtdal003264Source0002 = `get_plot_files = function() {
  unique(opts_knit$get('plot_files'))
}`

const rtdal003264Source0003 = `hook_optipng = function(...) hook_png(..., cmd = 'optipng')`

const rtdal003264Source0004 = `hook_png = function(
  before, options, ..., cmd = c('optipng', 'pngquant', 'mogrify'), post_process = identity
) {
  if (before) return()
  cmd = match.arg(cmd)
  if (!nzchar(Sys.which(cmd))) {
    warning('cannot find ', cmd, '; please install and put it in PATH'); return()
  }
  opts = options[[cmd]]
  if (isFALSE(opts)) return()
  if (is.null(opts) || isTRUE(opts)) opts = switch(
    cmd, optipng = '-quiet', pngquant = '--skip-if-larger', mogrify = '-trim'
  )
  if (cmd == 'pngquant') opts = c(opts, '--ext', '-fs8.png')

  paths = get_plot_files()
  paths = grep('[.]png$', paths, ignore.case = TRUE, value = TRUE)

  in_base_dir(
    lapply(paths, function(x) {
      system2(cmd, c(opts, shQuote(x)))
      post_process(x)
    })
  )
  return()
}`

const rtdal003264Source0005 = `hook_pngquant = function(...) {
  hook_png(..., cmd = 'pngquant', post_process = function(x) {
    # pngquant creates an output file with '-fs8.png' as the extension.
    x2 = sub("\\.png$", "-fs8.png", x)
    if (file.exists(x2)) file.rename(x2, x)
  })
}`

const rtdal003264Source0006 = `hook_mogrify = function(...) hook_png(..., cmd = 'mogrify')`

const rtdal003264Source0007 = `hook_plot_custom = function(before, options, envir){
  if (before) return() # run hook after the chunk
  if (options$fig.show == 'hide') return() # do not show figures

  ext = dev2ext(options)
  hook = knit_hooks$get('plot')

  n = options$fig.num
  if (n == 0L) n = options$fig.num = 1L # make sure fig.num is at least 1
  res = unlist(lapply(seq_len(n), function(i) {
    options$fig.cur = i
    hook(fig_path(ext, options, i), reduce_plot_opts(options))
  }), use.names = FALSE)
  paste(res, collapse = '')
}`

const rtdal003264Source0008 = "hook_purl = function(before, options, ...) {\n  # at the moment, non-R chunks are ignored; it is unclear what I should do\n  if (before || !options$purl || options$engine != 'R') return()\n\n  output = .knitEnv$tangle.file\n  if (isFALSE(.knitEnv$tangle.start)) {\n    .knitEnv$tangle.start = TRUE\n    unlink(output)\n    # write out knit_params() data from YAML\n    params = .knitEnv$tangle.params\n    if (length(params)) write_utf8(params, output)\n    .knitEnv$tangle.params = NULL\n  }\n\n  # `options` contains merged chunk options, but we need to check if\n  # `error=TRUE` in local chunk options, so retrieve options from knit_code\n  error = attr(knit_code$get(options$label), 'chunk_opts')[['error']]\n  code = tangle_mask(options$code, options$eval, error)\n  if (is.character(output)) {\n    code = c(\n      if (file.exists(output)) read_utf8(output),\n      label_code(code, options)\n    )\n    write_utf8(code, output)\n  }\n  invisible()\n}"

