const rtdal003303Source0002 = "assert('detect_pattern() automatically detects syntax patterns', {\n  (detect_pattern('<<>>=') %==% 'rnw')\n  (detect_pattern('<<foo, bar=TRUE>>=') %==% 'rnw')\n  (detect_pattern('% begin.rcode') %==% 'tex')\n  (detect_pattern('<!--begin.rcode') %==% 'html')\n  (detect_pattern('``` {r}') %==% 'md')\n  (detect_pattern('asdf', 'rnw') %==% 'rnw')\n  (is.null(detect_pattern('foo')))\n})"

const rtdal003303Source0003 = `assert('group_pattern() checks if a pattern contains a group', {
  (group_pattern('(.*)'))
  (!group_pattern('()'))
  (!group_pattern('abc'))
  (!group_pattern(NULL))
})`

const rtdal003303Source0005 = `assert('patterns for Rnw', {
  (grep(ce_rnw, '  @') %==% 1L) # spaces before @
  (grep(ce_rnw, '@  ') %==% 1L) # spaces after @
  (grep(ce_rnw, '@ %asdf') %==% 1L) # comments after %
  (grep(ce_rnw, '@ asdf') %==% integer()) # only spaces/comments allowed
  (grep(ce_rnw, ' @ a% sdf') %==% integer())
})`

const rtdal003303Source0007 = "assert('patterns for md', {\n  # Chunk options\n  (grepl(cb_md, '```{r}'))\n  (grepl(cb_md, '```{r label}'))\n  (grepl(cb_md, '```{r, eval=FALSE}'))\n  (grepl(cb_md, '```{awk}'))\n  # Pandoc's fenced code attributes\n  (!grepl(cb_md, '```{.class}'))\n  (!grepl(cb_md, '```{#id}'))\n  (!grepl(cb_md, '```{style=\"color: red\"}'))\n  # Pandoc's raw attribute\n  (!grepl(cb_md, '```{=latex}'))\n})"

